/**
 * Petshop Anketa→Augintinio profilis 301 v1 (LIVE)
 *
 * /anketa-testas/ (testinis, ID 34676) → /augintinio-profilis/ (ID 34789).
 *
 * KODEL SNIPPET'AS, NE CHILD THEME: visi aktyvus 301 (613 Shop→Parduotuve,
 * 632 Slapuku Politika ES, 634 Brand Slug) gyvena Code Snippets. Iskelus VIENA
 * i child theme, redirectai atsidurtu dviejose sistemose ir migruojant i
 * petshop.lt viena butu lengva pamirsti.
 *
 * home_url() — NE hardcode dev.avesa.lt: po domeno perjungimo veiks be pataisu.
 * Nesiremiam is_page(34676) — veiks ir tada, kai senas puslapis bus istrintas.
 * Prioritetas 1 ant template_redirect — pries bet kokia kita logika.
 * Tikslus kelio sutapimas — subkeliai ir panasus URL NELIECAMI.
 */
add_action(
	'template_redirect',
	static function (): void {
		$request_path = wp_parse_url( $_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH );
		$old_path     = wp_parse_url( home_url( '/anketa-testas/' ), PHP_URL_PATH );

		if ( untrailingslashit( (string) $request_path ) !== untrailingslashit( (string) $old_path ) ) {
			return;
		}

		wp_safe_redirect( home_url( '/augintinio-profilis/' ), 301, 'Petshop Legacy Redirect' );
		exit;
	},
	1
);
